import unittest,re
from tools.kjv_archive import load_register,read
class RevelationThroneSealsTests(unittest.TestCase):
 def test_shared_song_and_numbered_seals(self):
  prior,_=load_register('0.10-kjv.271');lang,manifest=load_register('0.10-kjv.272')
  self.assertEqual(prior.lexicon,{k:lang.lexicon[k] for k in prior.lexicon})
  for attr in ('pairs','suffix','prefix','possessors','roman'):self.assertEqual(getattr(prior,attr),getattr(lang,attr))
  cases={c['id'].removeprefix('revelation-'):c for c in read(lang.folder/'revelation-throne-and-seals-cases.json')};self.assertEqual(len(cases),42)
  for c in cases.values():
   r=lang.compile(c['analysis']);self.assertEqual(c['expectedText'],r['text']);self.assertEqual(c['expectedGloss'],r['gloss']);self.assertNotIn('!',r['text'])
   self.assertFalse({'one','matter','worship'}-{'worship'}&set(r['keys']))
  anchors={'4:1': ['i look:pa', 'first voice', 'ipl to thee', 'after this be:must'], '4:2': ['i in spirit', 'one_num upon throne'], '4:3': ['kjv_jasper and kjv_sardine_stone_revelation', 'kjv_rainbow_revelation', 'like kjv_emerald'], '4:4': ['two+twelve seat:pl', 'two+twelve kjv_elder:pl', 'their/head:pl gold crown:pl'], '4:5': ['lightning:pl and thunder:ev:pl and voice:pl', 'seven fire lamp:pl', 'god seven spirit:pl'], '4:6': ['glass sea like crystal', 'four beast:pl', 'before and behind eye:pl'], '4:7': ['first beast like lion', 'second beast like kjv_calf', 'third beast face as man', 'fourth beast like fly:cv kjv_eagle'], '4:8': ['four beast:pl each six wing:pl', 'day and night rest:neg:pr', 'holy holy holy', 'who be:pa and be:pr and come:fu'], '4:9': ['glory and honour and thanks', 'forever and forever live:pr'], '4:10': ['two+twelve kjv_elder:pl', 'their/crown:pl before throne cast:pr'], '4:11': ['thy/pleasure', 'they be:pr and create:psv:pa'], '5:1': ['kjv_right_side hand book', 'within and on back side', 'seven seal:pl'], '5:2': ['strong angel', 'book open:inf and its/seal:pl loose:inf:q'], '5:3': ['in heaven nor in earth neither under earth', 'neither upon it look:inf'], '5:4': ['i much weep:pa', 'book open:inf and read:inf'], '5:5': ['one_num of kjv_elder:pl', 'kjv_juda_hebrews kjv_tribe lion kjv_david root', 'its/seven seal:pl'], '5:6': ['four beast:pl', 'as slay:psv:perf stand:pa', 'seven horn:pl and seven eye:pl', 'god seven spirit:pl'], '5:7': ['he come:pa', 'kjv_right_side hand book take:pa'], '5:8': ['four beast:pl and two+twelve kjv_elder:pl', 'kjv_vial_fragrance_revelation:pl odour:pl full', 'holy person:pl prayer:pl'], '5:9': ['wesg:a to god by thy/blood', 'every kjv_family and tongue and people and nation'], '5:10': ['wesg:a to ourone/god king:pl and priest:pl', 'wesg upon earth rule:fu'], '5:11': ['their/kjv_number:ev ten+thousand+ten+thousand', 'thousand:pl of thousand:pl'], '5:12': ['power and wealth and wisdom and strength and honour and glory and blessing'], '5:13': ['in heaven and upon earth and under earth', 'in sea', 'to he who upon throne sit:pr and to kjv_lamb'], '5:14': ['four beast:pl amen', 'two+twelve kjv_elder:pl', 'he who forever and forever live:pr kjv_worship:pa'], '6:1': ['one_num of seal:pl', 'one_num of four beast:pl come:imp and see:imp'], '6:2': ['white horse', 'kjv_bow have:pa', 'crown give:psv:pa', 'conquer:cv and to conquer:inf'], '6:3': ['second seal', 'second beast come:imp and see:imp'], '6:4': ['other horse which red', 'from earth peace take:inf', 'they each other kill:should', 'great sword'], '6:5': ['third seal', 'third beast come:imp and see:imp', 'black horse', 'kjv_balances_revelation'], '6:6': ['four beast:pl', 'one_num kjv_measure_portion wheat for one_num kjv_penny_source', 'three kjv_measure_portion:pl kjv_barley for one_num kjv_penny_source', 'oil and wine hurt:neg:imp'], '6:7': ['fourth seal', 'fourth beast voice come:imp and see:imp'], '6:8': ['kjv_death_rider_revelation', 'kjv_hell_follower_revelation', 'earth kjv_fourth_share', 'with sword and with hunger and with death and with earth beast:pl'], '6:9': ['five:ord seal', 'under altar', 'god word and for testimony'], '6:10': ['how long', 'ourone/blood judge:neg:pr and kjv_avenge:neg:pr:q'], '6:11': ['kjv_robe:pl to each', 'little season rest:should', 'their/kjv_fellowservant_revelation:pl also and their/brother:pl', 'fulfil:psv:may'], '6:12': ['six:ord seal', 'earthquake', 'hair kjv_sackcloth', 'moon as blood'], '6:13': ['heaven star:pl to earth', 'her/kjv_untimely_fig_revelation fig:pl', 'mighty wind'], '6:14': ['heaven as scroll', 'every mountain and kjv_isle'], '6:15': ['king:pl and great man:pl and rich man:pl and chief captain:pl and mighty man:pl and every slave and every free man', 'kjv_den:pl'], '6:16': ['upon wesg fall:imp', 'wesg:a', 'from kjv_lamb wrath'], '6:17': ['his/wrath great day', 'who stand:inf able be:fu:q']}
  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('i look:pa',cases['4-1']['analysis'])
  self.assertIn('ipl to thee',cases['4-1']['analysis'])
  self.assertIn('they be:pr and create:psv:pa',cases['4-11']['analysis'])
  self.assertIn('wesg:a to ourone/god king:pl and priest:pl',cases['5-10']['analysis'])
  self.assertIn('thousand:pl of thousand:pl',cases['5-11']['analysis'])
  for ref in ('6-1','6-3','6-5','6-7'):self.assertIn('come:imp and see:imp',cases[ref]['analysis'])
  self.assertIn('earth kjv_fourth_share',cases['6-8']['analysis'])
  self.assertIn('his/wrath',cases['6-17']['analysis'])
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),8)
  self.assertEqual(manifest['baseForgeHead'],read(prior.folder/'manifest.json')['forgeHead'])
